from pathlib import Path
p=Path('android/app/src/main/java/in/tallybridge/app/OfflineOrdersStore.java')
s=p.read_text(encoding='utf-8')
old=''' void replaceWithRemote(JSONObject remote)throws Exception {synchronized(OfflineOrdersStore.class){JSONObject old=state();JSONArray current=old.optJSONArray("orders");Map<String,String> paths=localPhotoPaths(current);LinkedHashMap<String,JSONObject> merged=new LinkedHashMap<>();for(String key:new String[]{"pending","dispatched"}){JSONArray incoming=remote.optJSONArray(key);if(incoming==null)continue;for(int i=0;i<incoming.length();i++){JSONObject o=incoming.optJSONObject(i);if(o!=null)putMerged(merged,decorate(restoreLocalPaths(clone(o),paths)));}}if(current!=null)for(int i=0;i<current.length();i++){JSONObject local=current.optJSONObject(i);if(hasLocalMutation(local))putMerged(merged,decorate(restoreLocalPaths(clone(local),paths)));}JSONArray all=new JSONArray();for(JSONObject o:merged.values())all.put(o);write(STATE,new JSONObject().put("orders",all));}}\n'''
new=''' void replaceWithRemote(JSONObject remote)throws Exception {synchronized(OfflineOrdersStore.class){JSONObject old=state();JSONArray current=old.optJSONArray("orders");Map<String,String> paths=localPhotoPaths(current);LinkedHashMap<String,JSONObject> merged=new LinkedHashMap<>();Map<String,JSONObject> remoteByPhoneToken=new HashMap<>();for(String key:new String[]{"pending","dispatched"}){JSONArray incoming=remote.optJSONArray(key);if(incoming==null)continue;for(int i=0;i<incoming.length();i++){JSONObject raw=incoming.optJSONObject(i);if(raw==null)continue;JSONObject o=decorate(restoreLocalPaths(clone(raw),paths));putMerged(merged,o);JSONObject d=o.optJSONObject("buyerDetails");String token=d==null?"":d.optString(PHONE_TOKEN);if(!token.isEmpty())remoteByPhoneToken.put(token,o);}}if(current!=null)for(int i=0;i<current.length();i++){JSONObject local=current.optJSONObject(i);if(!hasLocalMutation(local))continue;JSONObject keep=decorate(restoreLocalPaths(clone(local),paths));String localId=keep.optString("id");JSONObject server=remoteByPhoneToken.get(localId);if(server!=null){String serverId=server.optString("id");keep.put("id",serverId).put("number",server.optString("number",keep.optString("number"))).put("createdAt",server.optString("createdAt",keep.optString("createdAt")));JSONObject details=keep.optJSONObject("buyerDetails");if(details==null)details=new JSONObject();details.put(PHONE_TOKEN,localId);keep.put("buyerDetails",details);JSONArray localAtt=keep.optJSONArray("attachments"),serverAtt=server.optJSONArray("attachments");if((localAtt==null||localAtt.length()==0)&&serverAtt!=null)keep.put("attachments",clone(serverAtt));keep.remove("_localOnly");keep.put("_dirty",true);merged.put(serverId,keep);}else putMerged(merged,keep);}JSONArray all=new JSONArray();for(JSONObject o:merged.values())all.put(o);write(STATE,new JSONObject().put("orders",all));}}\n'''
if s.count(old)!=1: raise SystemExit(f'replaceWithRemote baseline changed: {s.count(old)}')
p.write_text(s.replace(old,new,1),encoding='utf-8')
